.gradient-border {
    position: relative;
    border: none;
    border-radius: 12px; /* ajuste conforme necessário */
    overflow: hidden;
}

.gradient-border::before {
    content: "";
    position: absolute;
    inset: 0;
    padding: 1.5px; /* espessura da borda */
