page_settings.custom_css:
/* trava o scroll horizontal de forma mais robusta */
html, body {
  overflow-x: hidden ;   /* clip pega até fixed/sticky, hidden não */
  max-width: 100% !important;
}

/* garante que o sheet fora da tela não empurre a largura */
#mrs-sheet,
#mrs-sheet-overlay {
  max-width: 100vw;
}

::selection {
    background-color: rgba(255, 255, 255, 0.125);
}

p:last-of-type {
    margin-bottom: 0;
}

body::-webkit-scrollbar {
    width: 10px; /* largura da barra de rolagem */
}

body::-webkit-scrollbar-track {
    background-color: #111111; /* cor da área de rastreamento */
}

body::-webkit-scrollbar-thumb {
    background: linear-gradient(90deg, #fff, #fff); /* cor do SCROLL*/
    border-radius: 15px; /* arredondamento do SCROLL */
    border: 2px solid #111111; /* cria espaçamento em torno do SCROLL*/
}

.destaque1{
    font-style:italic;
    color:#6F9FC8;
}

/*ANIMACAO ENTRADA*/

.scroll-left,
.scroll-right,
.scroll-bottom,
.scroll-top {
    opacity: 0;
    filter: blur(10px); /* aqui o blur inicial */
    transition: 0.6s all ease;
}

/* Mantém seus transforms separados */
.scroll-left {
    transform: translate3d(-30px, 0, 0);
}

.scroll-right {
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom {
    transform: translate3d(0, 80px, 0);
}

.scroll-top {
    transform: translate3d(0, -80px, 0);
}

/* Estado ativo */
.ativo {
    opacity: 1;
    filter: blur(0); /* remove o blur */
    transform: translate3d(0, 0, 0);
}
